"""Migrated Meridian CRM credit-hold sweep."""

from decimal import Decimal, InvalidOperation
from fractions import Fraction


def _numeric_value(value) -> Fraction:
    """Return a finite decimal value, treating empty or missing values as zero."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Fraction(0)

    if isinstance(value, bool):
        return Fraction(int(value))

    try:
        decimal_value = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Fraction(0)

    if not decimal_value.is_finite():
        return Fraction(0)

    return Fraction(decimal_value)


def _account_sort_key(account: dict):
    """Provide a deterministic ascending primary-key ordering."""
    acct_id = account.get("ACCT_ID")

    if acct_id is None:
        return (0, Decimal(0), "")

    try:
        numeric_id = Decimal(str(acct_id))
        if numeric_id.is_finite():
            return (1, numeric_id, "")
    except (InvalidOperation, ValueError):
        pass

    return (2, Decimal(0), str(acct_id))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, object]] = []

    exposure_by_account: dict[object, Fraction] = {}
    for order in orders:
        if order.get("DEL_FLG") != "Y" and order.get("STAT_CD") == "I":
            acct_id = order.get("ACCT_ID")
            exposure_by_account[acct_id] = (
                exposure_by_account.get(acct_id, Fraction(0))
                + _numeric_value(order.get("TOT_AMT"))
            )

    eligible = [
        (index, account)
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible.sort(key=lambda item: _account_sort_key(item[1]))

    for index, account in eligible:
        acct_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(acct_id, Fraction(0))
        credit_limit = _numeric_value(account.get("CRED_LIMIT"))
        hold = new_accounts[index].get("CRED_HOLD")

        if exposure > credit_limit and hold != "Y":
            hold = "Y"
            new_accounts[index]["CRED_HOLD"] = hold
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * 8 / 10 and hold == "Y":
            hold = "N"
            new_accounts[index]["CRED_HOLD"] = hold
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
